"""R2 text changes relative to the R1 submission (PGPH_r2_cleaned_edited.docx), keyed by R1 paragraph index.
SPEC[i] is a list of (kind, style, text): kind 'R' replaces R1 paragraph i (style None = keep R1 style);
kind '+' inserts a new paragraph after it. A list without an 'R' item deletes R1 paragraph i.
All numbers are taken from r2/data (no hard-coded results)."""
import json
from pathlib import Path
import pandas as pd
ROOT = Path(__file__).resolve().parents[2]
H1, H2, NB, LB, LN = "Heading 1", "Heading 2", "Normal", "List Bullet", "List Number"


def build(N=None):
    N = N or json.load(open(ROOT / "r2/data/r2_numbers.json"))
    m = pd.read_csv(ROOT / "r2/data/r2_master_jurisdictions.csv")
    c, p, b = N["counts"], N["pct"], N["burden"]
    pb, gb = b["primary"], b["gcc_collapsed"]
    st = m.r1_search_stage.value_counts()
    ct = pd.crosstab(m.r1_search_stage, m.r2_category)
    nA, nAu, nB, nC, nD, T = c["A"], c["A_unverified"], c["B"], c["C"], c["D"], N["N"]
    W = lambda n: ["Zero","One","Two","Three","Four","Five","Six","Seven","Eight","Nine","Ten"][n] if n <= 10 else str(n)
    f2 = lambda x: f"{x:.2f}".replace("-", "−")
    S = {}
    S[0] = [("R", None, f"Policies without evidence, populations without recourse: Hansen’s disease screening in work visa medical examinations across {T} jurisdictions")]
    S[11] = [("R", None, "Background\nHansen’s disease (leprosy) is a curable chronic infection caused by Mycobacterium leprae. Some jurisdictions still name it in medical requirements for migrant workers, but the extent, legal nature and treatment-status provisions of these requirements have not been systematically mapped.")]
    S[12] = [("R", None, "Objectives\nTo identify jurisdictions requiring disease-specific medical screening of work visa applicants, verify which name Hansen’s disease in an operative official instrument, and characterize the legal tier, timing, consequences, treatment-status provisions and origin-based applicability of these requirements.")]
    S[13] = [("R", None, f"Methods\nWe conducted a scoping review following PRISMA-ScR guidelines across {T} jurisdictions ({N['frame']['UN member State']} UN Member States and {N['frame']['Non-UN entity']} non-UN jurisdictions). Sources included legislation, official examination forms and programme documents, the ILEP discriminatory laws database, IOM reports, and literature. Jurisdictions classified as naming Hansen’s disease were re-verified against archived primary sources and classified by legal tier. National leprosy burden was compared using WHO new case detection rates.")]
    S[14] = [("R", None, f"Results\nDisease-specific screening was reported in {N['screening_reported']} of {T} jurisdictions ({N['screening_reported_pct']}%). Hansen’s disease was named in a verified operative instrument in {nA} jurisdictions ({p['A']}%) applying {W(N['A_policy_units']).lower()} distinct policies: the GCC states’ regional WAFID programme, the United States, South Africa, Thailand, Russia and Taiwan. {W(nAu)} further jurisdictions were unconfirmed. Three policies are statutory or regulatory grounds and three are administrative fitness-to-work protocols. Only the United States and Taiwan explicitly distinguish treated from untreated disease; Thailand limits exclusion to the contagious stage or visible symptoms. Taiwan’s examination applies according to workers’ origin. National leprosy new case detection rates did not differ clearly between these and other classified jurisdictions (median difference {f2(pb['median_diff'])} per million; 95% CI {f2(pb['median_diff_boot95'][0])} to {f2(pb['median_diff_boot95'][1])}), in an underpowered comparison.")]
    S[15] = [("R", None, "Conclusions\nHansen’s disease remains named in work-related medical requirements in a few jurisdictions, through legally distinct instruments that mostly do not distinguish infectious disease from treated disease or its sequelae. These provisions warrant review against current clinical evidence and UN Resolution A/RES/65/215.")]
    S[20] = [("R", None, "Hansen’s disease (leprosy), caused by Mycobacterium leprae, is among the oldest documented infectious diseases in human history [@scollard2006]. Since the introduction of WHO’s multidrug therapy (MDT) in 1981, the disease has been curable with 6–12 months of treatment [@who2018], yet it continues to carry profound social stigma in many parts of the world [@sermrittirong2014].")]
    S[21] = [("R", None, "The global epidemiological picture has improved substantially. The WHO reported approximately 182,000 new cases detected globally in 2024, with new case detection rates declining steadily over the past two decades [@wer2025]. Transmission is thought to occur mainly through the respiratory route after prolonged close contact with untreated patients, particularly those with multibacillary disease, although other routes and reservoirs have been described [@bratschi2015;@araujo2016;@ploemacher2020]. Most exposed people do not develop disease, and the risk among contacts increases with physical and genetic closeness to the index patient and with the patient’s bacillary load [@fine1982;@moet2006]. The incubation period is typically several years and may exceed a decade, so a single medical examination at the time of migration cannot exclude later disease [@scollard2006;@britton2004].")]
    S[23] = [("R", None, "The international community has explicitly addressed leprosy-related discrimination. UN General Assembly Resolution A/RES/65/215 (2010) calls upon states to eliminate discrimination against persons affected by Hansen’s disease, with Principle 7 affirming the right to freedom of movement including entry into countries [@unga2010]. A UN Special Rapporteur on the elimination of discrimination against persons affected by leprosy was appointed in 2017 [@unhrc2017]. The International Federation of Anti-Leprosy Associations (ILEP) maintains a database documenting 139 discriminatory laws across 24 countries [@ilep]; S3 Appendix cross-references this database with the findings of this review.")]
    S[24] = [("R", None, "Disease-based restrictions on migrant workers are imposed through legally distinct instruments, which differ in authority, accountability and remedies. We therefore distinguish three legal tiers. (1) Statutory or regulatory immigration-law grounds: provisions in immigration legislation or its implementing regulations that make a health condition a ground for refusing a visa, residence or work authorization, such as the United States health-related grounds of inadmissibility, under which communicable diseases of public health significance are “Class A” conditions [@cfr42;@cdcti]. (2) Administrative fitness-to-work protocols: examination criteria issued by health or labour authorities, or by regional bodies such as the Gulf Health Council’s WAFID programme (formerly GAMCA), under which a medical result of “unfit” is issued before departure or at work registration [@wafid]. (3) Removal or prohibition triggers: provisions that require departure, annul an existing authorization or prohibit entry once a condition is found, for which the availability of reasons, review or appeal must be examined separately. A medical finding of “unfit” is therefore not automatically equivalent to a statutory refusal or to deportation, and the absence of a located appeal provision does not establish that no appeal exists.")]
    S[28] = [("R", None, "(2) How many and which jurisdictions name Hansen’s disease in an operative official instrument, and at which legal tier?")]
    S[29] = [("R", None, "(3) What are the timing, consequences, treatment-status provisions and review mechanisms of these provisions, and do they apply differently according to applicants’ country of origin?")]
    S[30] = [("R", None, "(4) Is the presence of these provisions related to national leprosy burden?")]
    S[35] = [("R", None, "This scoping review was conducted in accordance with the PRISMA Extension for Scoping Reviews (PRISMA-ScR) [@tricco2018] and the methodological framework proposed by Arksey and O’Malley [@arksey2005] as enhanced by Levac et al. [@levac2010]. The protocol was developed a priori. The completed PRISMA-ScR checklist is provided in S1 Appendix.")]
    S[37] = [("R", None, f"Population: {T} jurisdictions, comprising the {N['frame']['UN member State']} UN Member States, the two UN General Assembly non-member observer States (Holy See and State of Palestine), Taiwan, Kosovo and the Hong Kong Special Administrative Region. The US Virgin Islands, which applies United States federal immigration law, is included within the United States. The original submission described this frame as 197 entities; reconciliation of the underlying lists showed that Hong Kong SAR had been analysed but not counted and that the US Virgin Islands had been counted separately (S2 Appendix).")]
    S[39] = [("R", None, "Context: Medical requirements for work visas, work permits or work registration as codified in national legislation, regulations, official medical examination forms, and official national or regional administrative programme documents.")]
    S[55] = [("R", None, "Data were extracted into a standardized charting form that captured: country/territory name; UN membership status; geographic region; work visa types requiring medical examination; specific diseases named in requirements; whether Hansen’s disease is explicitly listed; the nature of the provision; legal instrument source; and year of legislation/regulation. In revision, we added the instrument level (statute, regulation, official form or programme document), legal tier, applicable pathway, timing (pre-departure, at application or post-entry), consequence, any distinction by treatment status, any review or waiver mechanism stated in the located source, and any applicability by country of origin."),
             ("+", H2, "2.6 Primary-Source Verification"),
             ("+", NB, "Between 5 and 19 November 2026, every jurisdiction classified as naming Hansen’s disease in the original submission was re-verified against the current text of the cited or operative instrument. Official sources were retrieved, archived with retrieval time and SHA-256 checksum, and searched for “leprosy”, “Hansen” and equivalent terms in the original language (S5 Appendix). A jurisdiction was retained in Category A only if leprosy or Hansen’s disease was named in an operative official instrument (statute, regulation, official medical form or official programme document) governing the medical examination for work visas, work permits or work registration. Provisions that delegate the list of diseases to regulations that could not be located were not counted as naming Hansen’s disease. Classifications in Categories B and D were not re-verified and are reported as recorded in the original search.")]
    S[56] = [("R", None, "2.7 Synthesis of Results")]
    S[57] = [("R", None, "Results were synthesized using a descriptive analytical approach. Jurisdictions were assigned to mutually exclusive categories: A, Hansen’s disease named in a verified operative instrument; A-unverified, classified in the original search as naming Hansen’s disease but not confirmed in located primary sources; B, disease-specific screening reported but Hansen’s disease not named; C, requirements unresolved; and D, no disease-specific requirement identified. Geographic distribution patterns were mapped. The disease-frequency ranking reported in the original submission was withdrawn because the underlying jurisdiction-by-disease data could not be reconstructed."),
             ("+", H2, "2.8 Comparison with National Leprosy Burden"),
             ("+", NB, "For each jurisdiction we linked the most recent WHO new case detection rate per 1,000,000 population reported for 2019–2025 (WHO Global Health Observatory indicator NTD_LEPR2) [@who_gho]. We compared Category A with Categories B and D combined using the Mann–Whitney U test, and report medians with interquartile ranges, the difference in medians with a percentile bootstrap 95% confidence interval (5,000 resamples) and the rank-biserial correlation. Because the six GCC states apply one regional rule, a sensitivity analysis counted them as one unit. Jurisdictions without WHO data were excluded from this comparison. The burden of the destination jurisdiction is not a measure of risk among arriving workers, so this analysis addresses only whether provisions track domestic burden.")]
    S[61] = [("R", None, f"Of the {T} jurisdictions examined, work-related medical requirements were characterized through English-language sources for {st['english']} and through supplementary multilingual searches for {st['multilingual']}; {st['unreachable']} jurisdictions remained unresolved after both stages. These counts differ slightly from the original submission (110 and 87) because of the corrected jurisdiction frame (S2 Appendix).")]
    S[62] = [("R", None, f"To address this gap, supplementary searches were conducted in official languages (Arabic, Vietnamese, Sinhala, Indonesian, and others) for countries where English information was insufficient. This multilingual research successfully identified specific disease screening requirements for 5 additional countries: Jordan (tuberculosis, HIV, hepatitis B/C, syphilis), Lebanon (VDRL, HIV, cholera, malaria, hepatitis B), Vietnam (HIV, hepatitis B, syphilis, malaria), Sri Lanka (tuberculosis, HIV, malaria, filariasis), and Indonesia (primarily tuberculosis). None of these countries screened for Hansen’s disease. For the remaining {st['unreachable']} jurisdictions, specific diseases could not be confirmed despite multilingual research. The flow of jurisdictions through the search and re-verification stages is presented in Figure 1.")]
    e = ct.loc["english"]
    S[66] = [("R", None, f"The distribution of categories by search stage is shown in Figure 2. Of the {st['english']} jurisdictions characterized through English-language sources, {e['A']} were classified as Category A, {e['A_unverified']} as A-unverified, {e['B']} as B and {e['D']} as D, and {e['C']} (India) was reclassified as unresolved in revision; all {st['multilingual']} jurisdictions characterized through multilingual searches were classified as Category B.")]
    S[70] = [("R", None, f"The geographic distribution of data accessibility is shown in Figure 3. Unresolved jurisdictions are concentrated in Sub-Saharan Africa, Central and West Asia, and non-EU Europe. The full list of the {nC} jurisdictions classified as unresolved (the {st['unreachable']} unresolved after both search stages and India, reclassified in revision), with their official languages, is provided in S4 Appendix.")]
    S[75] = [("R", None, f"The {T} jurisdictions were categorized as follows:")]
    S[76] = [("R", None, f"Category A: Hansen’s disease named in a verified operative instrument — {nA} jurisdictions ({p['A']}%)"),
             ("+", LB, f"Category A-unverified: classified as naming Hansen’s disease in the original search but not confirmed in located primary sources — {nAu} jurisdictions ({p['A_unverified']}%)")]
    S[77] = [("R", None, f"Category B: Disease-specific screening reported but Hansen’s disease not named — {nB} jurisdictions ({p['B']}%)")]
    S[78] = [("R", None, f"Category C: Requirements unresolved — {nC} jurisdictions ({p['C']}%)")]
    S[79] = [("R", None, f"Category D: No disease-specific requirement identified — {nD} jurisdictions ({p['D']}%)"),
             ("+", NB, f"Disease-specific screening was therefore reported in {N['screening_reported']} jurisdictions ({N['screening_reported_pct']}%; Categories A, A-unverified and B). The original submission reported 58 jurisdictions with confirmed disease-specific screening and 20 naming Hansen’s disease; the differences arise from the corrected jurisdiction frame, the inclusion of the five jurisdictions characterized by multilingual search, and the re-verification described below.")]
    S[84] = [("R", None, "3.3 Jurisdictions Naming Hansen’s Disease: Verification and Legal Taxonomy")]
    S[85] = [("R", None, f"Re-verification confirmed that Hansen’s disease is named in an operative official instrument in {nA} jurisdictions, which apply {W(N['A_policy_units']).lower()} distinct policies (Table 1; Figure 5): the regional WAFID programme of the six GCC states, and national provisions in the United States, South Africa, Thailand, Russia and Taiwan. For {W(nAu).lower()} jurisdictions classified as Category A in the original submission (Barbados, China, Hong Kong SAR, Malaysia, Malta, Namibia and the Philippines), the located primary sources did not name Hansen’s disease or could not be retrieved; for example, China’s Exit and Entry Administration Law names infectious pulmonary tuberculosis but not leprosy [@cn]. India was reclassified as unresolved because the cited provisions are state employment laws rather than work-visa medical requirements, and the US Virgin Islands was merged with the United States because the same federal law applies.")]
    S[86] = [("R", None, "Table 1: Legal taxonomy of jurisdictions classified as naming Hansen’s disease in the original submission")]
    S[87] = [("R", None, "A, Hansen’s disease named in a verified operative instrument; A-unverified, not confirmed in located primary sources. Archived sources, retrieval dates and checksums are listed in S5 Appendix. GCC, Gulf Cooperation Council; WAFID, Gulf Health Council pre-departure medical examination programme (formerly GAMCA); MDT, multidrug therapy.")]
    S[88] = [("R", None, "Statutory or regulatory grounds. In the United States, “Hansen’s disease, infectious” is a communicable disease of public health significance under 42 CFR 34.2(b)(4) and therefore a health-related ground of inadmissibility under INA §212(a)(1)(A)(i) [@cfr42]; this examination applies to immigrant visa applicants, refugees and applicants for adjustment of status, not to most temporary work visas. Under the CDC Technical Instructions, untreated disease is a Class A condition, whereas applicants who have received at least seven days of recommended therapy are reported as Class B, which is not a ground of inadmissibility [@cdcti]; the statement in our original submission that a waiver is granted for completion of MDT was inaccurate. In South Africa, the Immigration Act 13 of 2002 excludes from temporary and permanent residence foreigners infected with infectious diseases “as prescribed”, and the official medical certificate (BI-811) requires the examining practitioner to certify that the applicant is not suffering from leprosy [@za]. In Russia, Ministry of Health Order No. 384n lists leprosy (Hansen’s disease; ICD-10 A30) among the diseases that are grounds for refusal or annulment of a work permit, patent, temporary residence permit or residence permit [@ru384n]."),
             ("+", NB, "Administrative fitness-to-work protocols. The WAFID programme lists leprosy among the infectious conditions evaluated as “unfit”, without a stated distinction by treatment status, and separately lists “any distortion, amputation or physical disability impeding the applicant’s performance” [@wafid]. Thailand’s Ministry of Public Health notification, as summarized on the official government portal, bars from work registration migrant workers with “leprosy in the contagious stage or in the stage when symptoms appear appalling to society”, who must return to their country of origin [@th]. Taiwan’s Regulations Governing Health Examination of Employed Aliens require a Hansen’s disease examination for mainly blue-collar workers before visa issuance, within three days of entry and periodically thereafter; a worker diagnosed in Taiwan is treated and then deemed to have passed, and re-examination is provided [@tw_regs]."),
             ("+", NB, "Removal and review. Two provisions specify a consequence after entry that ends the right to work or remain: Thailand’s requirement to return to the country of origin and Russia’s refusal or annulment of work authorization. A review or waiver mechanism was stated in the located sources only for the United States (waiver) and Taiwan (re-examination). We did not locate appeal provisions for the other policies, but this does not establish that no appeal or review is available under general administrative law. The descriptions in our original submission of Russia as applying a “deportation ground” and of the GCC system as resulting in “immediate visa denial and repatriation” could not be verified in the located sources and have been removed.")]
    S[90] = [("R", None, "3.4 The GCC/WAFID Programme")]
    S[91] = [("R", None, "The six GCC states apply a common pre-departure medical examination through the WAFID programme of the Gulf Health Council (formerly the GCC Approved Medical Centers Association, GAMCA) [@wafid]. Examinations are conducted at accredited medical centres in 21 programme countries: Bangladesh, Egypt, Ethiopia, Ghana, India, Indonesia, Jordan, Kenya, Lebanon, Mali, Morocco, Nepal, Niger, Pakistan, the Philippines, Sri Lanka, Sudan, Tanzania, Thailand, Turkey and Uganda. The full WAFID medical examination regulations cited in the original submission could not be retrieved, and the statement that the system affects over 35 million migrant workers was not supported by a cited source and has been removed.")]
    S[92] = [("R", None, "3.5 Treatment Status and Post-MDT Sequelae")]
    S[93] = [("R", None, "Only two of the six policies explicitly distinguish untreated from treated disease: the United States (Class A only before at least seven days of therapy) and Taiwan (treatment pathway after diagnosis in Taiwan) [@cdcti;@tw_regs]. Thailand restricts the prohibition to the contagious stage but adds a criterion based on visible symptoms, which may apply to people with residual deformity irrespective of infectiousness [@th]. The WAFID, South African and Russian instruments name leprosy without reference to treatment status, MDT completion or cure [@wafid;@za;@ru384n]. None of the located instruments defines how residual lesions, nerve thickening or disability after completed MDT are to be assessed, and we found no published data on how examining physicians classify such findings in practice.")]
    for i in range(94, 101): S[i] = []
    S[101] = [("+", H2, "3.6 Applicability by Country of Origin"),
              ("+", NB, "Two policies apply differently according to the applicant’s origin (Table 1). Taiwan exempts skilled workers from a published list of countries and areas from the Hansen’s disease examination; the list comprises mainly high-income and European Region jurisdictions and excludes, by omission, India, Indonesia, Brazil, the Philippines, Viet Nam, Thailand and all African states [@tw_exempt]. The WAFID examination is conducted in 21 programme countries, including India, Indonesia and several African countries, and therefore applies to workers recruited from these countries; Brazil is not a programme country [@wafid]. We did not locate any instrument that prohibits entry of nationals of specific high-burden countries as such.")]
    S[105] = [("R", None, "3.7 National Leprosy Burden")]
    S[106] = [("R", None, f"WHO new case detection rates were available for {b['coverage']['with_rate']} of {T} jurisdictions (Figure 6). Among Category A jurisdictions with data (n = {pb['n_A']}; Taiwan is not covered by WHO data), the median rate was {f2(pb['A_median_iqr'][0])} per 1,000,000 (IQR {f2(pb['A_median_iqr'][1])}–{f2(pb['A_median_iqr'][2])}), compared with {f2(pb['BD_median_iqr'][0])} ({f2(pb['BD_median_iqr'][1])}–{f2(pb['BD_median_iqr'][2])}) among Category B and D jurisdictions (n = {pb['n_BD']}): difference in medians {f2(pb['median_diff'])} (bootstrap 95% CI {f2(pb['median_diff_boot95'][0])} to {f2(pb['median_diff_boot95'][1])}); Mann–Whitney p = {pb['p']:.2f}; rank-biserial correlation {f2(pb['rank_biserial'])}. Counting the GCC states as one unit gave a difference of {f2(gb['median_diff'])} (95% CI {f2(gb['median_diff_boot95'][0])} to {f2(gb['median_diff_boot95'][1])}; p = {gb['p']:.2f}). These estimates do not show a clear difference, but with only {W(N['A_policy_units']).lower()} independent policies the comparison cannot exclude a substantial association. The statement in our original submission that screening showed “no correlation with national leprosy burden” was not based on a formal analysis and has been replaced by these estimates.")]
    S[110] = [("R", None, "3.8 Jurisdictions Without Disease-Specific Requirements (Category D)")]
    S[111] = [("R", None, f"In total, {nD} jurisdictions were recorded in the original search as not requiring disease-specific medical screening for standard work visas. These include most European Union and European Free Trade Association member states, whose nationals benefit from free movement of workers; this classification does not exclude tuberculosis or other screening of third-country nationals or other migrant groups, which was not re-verified in revision. Jurisdictions recorded with disease-specific requirements that do not name Hansen’s disease (Category B) include Canada, Australia, the United Kingdom, New Zealand, Japan (TB-only pre-entry screening through JPETS for specific nationalities), South Korea and Singapore (Table 2).")]
    S[112] = [("R", None, "Table 2: Selected jurisdictions with disease-specific screening that does not name Hansen’s disease (n=11; as recorded in the original search, not re-verified)")]
    S[114] = []
    S[115] = []
    S[121] = [("R", None, f"This scoping review maps Hansen’s disease provisions in work-related medical requirements across {T} jurisdictions and verifies them against primary sources. Hansen’s disease is named in a verified operative instrument in {nA} jurisdictions ({p['A']}%), which apply {W(N['A_policy_units']).lower()} distinct policies; classification of {W(nAu).lower()} further jurisdictions reported in the original search could not be confirmed. The GCC WAFID programme is the only regional system identified and, because it is applied in 21 major origin countries, is likely to affect the largest number of workers, although we could not quantify this.")]
    S[122] = [("R", None, "4.2 Clinical and Epidemiological Considerations")]
    S[123] = [("R", None, "Several clinical and epidemiological features are relevant to whether examining migrant workers for Hansen’s disease can be justified. First, the disease is curable with MDT, which WHO provides free of charge, and rifampicin-containing treatment rapidly reduces the number of viable bacilli [@scollard2006;@who2018;@wer2025]. Second, transmission is thought to occur mainly through the respiratory route from untreated patients after prolonged close contact, and subclinical infection and nasal carriage have been documented among contacts in endemic settings; we therefore do not characterize M. leprae as non-aerosolizable [@bratschi2015;@araujo2016;@ploemacher2020]. Third, disease risk among contacts depends strongly on the closeness and duration of contact [@moet2006]. Fourth, because the incubation period is long and variable, a negative examination at migration cannot predict later disease, and an examination that detects established disease identifies a person who needs treatment rather than one whose exclusion prevents transmission [@scollard2006;@britton2004]. Fifth, estimates of the basic reproduction number of leprosy that are comparable with those for tuberculosis are not available, and we have removed the numerical R0 comparisons that appeared in the original submission.")]
    S[124] = [("R", None, f"Against this background, {W(N['A_policy_units']).lower()} policies name Hansen’s disease through statutory, regulatory and administrative instruments, and four of them (WAFID, South Africa, Russia, and Thailand through its visible-symptom criterion) do not confine exclusion to infectious disease. Such provisions are difficult to reconcile with WHO’s call to remove laws that discriminate against persons affected by leprosy [@who_strategy].")]
    S[125] = [("R", None, "Post-MDT status. Residual skin lesions, nerve thickening and disability may persist after successful MDT, whereas relapse after completed MDT is uncommon [@lockwood2012;@kaimal2009]. A provision that names leprosy without reference to infectiousness, or that excludes visible sequelae or physical disability, may therefore classify people who have been cured as unfit. Because none of the located instruments specifies how such findings are assessed, and because practice data are lacking, our findings show that these provisions permit such outcomes, not how often they occur. Whether these provisions reflect historical stigma cannot be established from legal texts alone, although their persistence is consistent with the concerns raised by the UN and the Special Rapporteur [@unga2010;@unhrc2017;@nanri2022].")]
    S[126] = [("R", None, "4.3 Proportionality of Border Health Measures")]
    S[127] = [("R", None, "Tuberculosis, the condition most frequently included in migrant screening programmes, differs from Hansen’s disease in ways that matter for border screening: it causes over one million deaths annually, active pulmonary disease can be detected at examination by chest radiography and sputum testing, and pre-entry screening programmes aim to reduce onward transmission [@tb2024;@seedat2018;@pareek2012]. Hansen’s disease is curable, has a global new case count below 200,000 per year, and cannot be excluded by a single examination [@wer2025].")]
    S[128] = [("R", None, "The concept of a threshold for border health intervention requires explicit definition. Drawing on the International Health Regulations (IHR, 2005) [@ihr] and the Siracusa Principles on the Limitation and Derogation Provisions in the International Covenant on Civil and Political Rights (1985) [@siracusa], we propose that legitimate border health interventions should satisfy the following criteria: (a) the disease must pose a significant risk of international spread through the specific population movement being regulated; (b) the screening measure must be effective in reducing that risk; (c) the intervention must be proportionate to the public health threat, considering disease transmissibility, severity, treatability, and the availability of less restrictive alternatives; and (d) the measure must not be applied in a discriminatory manner. Hansen’s disease provisions are difficult to reconcile with these criteria. Labour migration is not an established route of significant international spread; a single examination cannot detect infection that has not yet produced disease; less restrictive alternatives, such as referral for free MDT and examination of contacts, are available [@who2018]; and provisions that apply only to workers from particular origins (Taiwan, WAFID) or that target visible sequelae raise concerns about discrimination.")]
    S[130] = [("R", None, "Japan’s approach provides an instructive counter-example. Japan enacted its Leprosy Prevention Law in 1953, mandating forced isolation of persons with Hansen’s disease. This law was abolished in 1996 following sustained advocacy by former patients. In 2001, the Kumamoto District Court ruled that the government’s prolonged enforcement of forced isolation violated constitutional rights, resulting in formal apology and compensation [@kumamoto]. Crucially, Japan does not include Hansen’s disease in its immigration medical screening requirements. Japan’s pre-entry TB screening program (JPETS) demonstrates that evidence-based, disease-specific screening for immigration purposes is feasible—and that such programs need not include diseases that do not meet the threshold for border health intervention.")]
    S[135] = [("R", None, "Reports of the UN Special Rapporteur on leprosy (2017–present): Document ongoing discriminatory laws in immigration contexts [@nanri2022].")]
    S[138] = [("R", None, f"This review has several limitations. First, despite a two-stage search strategy, {st['unreachable']} jurisdictions remained unresolved after both stages and India was reclassified as unresolved in revision; together these {nC} jurisdictions ({p['C']}%) include many in Central Asia, Africa and the Middle East whose immigration portals and legislation are published in local languages (S4 Appendix). Machine translation was used for multilingual searches and not all translated documents were checked by native speakers. Language and access barriers may therefore have led to under-identification of provisions, and the absence of Hansen’s disease from the five jurisdictions characterized by multilingual search does not show that the {nA} verified jurisdictions are a complete enumeration. Second, only Category A was re-verified against primary sources in revision; Categories B and D are reported as recorded in the original search and may contain errors. Third, for {W(nAu).lower()} jurisdictions the operative instrument could not be retrieved or did not name Hansen’s disease; some may name it in regulations, forms or panel-physician instructions that are not publicly available.")]
    S[139] = [("R", None, f"Fourth, some countries’ requirements are communicated only to designated panel physicians and are not publicly documented, potentially leading to underestimation. Fifth, immigration medical requirements change frequently; our original search reflects information available as of March 2026 and the re-verification as of November 2026. Sixth, the existence of a legal provision does not necessarily reflect current enforcement practice—some countries may retain outdated provisions that are not actively applied. Seventh, the comparison with national leprosy burden is underpowered and uses destination-country burden, which is not a measure of risk among arriving workers. Eighth, this review focused exclusively on work visa medical examination requirements and did not assess screening practices affecting other migrant populations, including refugees, asylum seekers, and family reunification applicants. The absence of formal work visa screening requirements in a given country does not imply the absence of mandatory—and potentially discriminatory—health screening practices affecting these groups. For example, several European countries that do not require disease-specific screening for work visa applicants nonetheless conduct compulsory screening for tuberculosis, HIV, and hepatitis B among asylum seekers and refugees [@seedat2018;@pareek2012]. Whether Hansen's disease is included in such parallel screening programs warrants separate investigation and represents an important avenue for future research.")]
    S[142] = [("R", None, f"Hansen’s disease remains named in work-related medical requirements in {nA} verified jurisdictions applying {W(N['A_policy_units']).lower()} distinct policies, through statutory, regulatory and regional administrative instruments. Most of these provisions do not distinguish infectious disease from treated disease or its sequelae, and two apply differently according to workers’ countries of origin.")]
