def table1_rows():
    t = pd.read_csv(ROOT / "r2/data/r2_category_a_taxonomy.csv").fillna("")
    t = t[t.status != "excluded_from_A"]
    g = t.tier.str.startswith("Regional")
    t = pd.concat([t[~g & (t.status == "A_verified")], t[g].head(1).assign(name="GCC states (n = 6)"), t[t.status != "A_verified"]])
    rows = [["Jurisdiction", "Status", "Operative instrument located", "Legal tier; timing", "Consequence", "Treatment-status distinction", "Review or waiver stated", "Origin-based applicability"]]
    for r in t.itertuples():
        if r.status != "A_verified":
            rows.append([r.name, "A-unverified", r.instrument_short, "—", "—", "—", "—", "—"]); continue
        tier = "Statutory/regulatory" if r.legal_type == "statutory" else ("Regional administrative" if r.name.startswith("GCC") else "National administrative")
        tr = r.treatment_distinction.split(":")[0].split(" (")[0].split(";")[0]
        rows.append([r.name, "A", r.instrument_short, f"{tier}; {r.timing.split(' (')[0]}", r.consequence_short, tr,
                     "Yes: " + r.review.split(" (")[0] if r.review.startswith(("Waiver", "Re-exam")) else "Not stated",
                     "Yes (exemption list by origin)" if r.origin_targeting.startswith("Yes") else "Yes (examined in 21 programme countries)" if r.origin_targeting.startswith("Operates") else "No"])
    return rows
